import { API_URL, GROQ_API_KEY } from "./config.ts";
import { trace } from "./diagnostics.ts";
import { logger } from "./logger.ts";

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface Usage {
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
}

export interface ChatResult {
  content: string;
  reasoning?: string;
  usage: Usage;
  model: string;
}

export interface ChatOptions {
  model: string;
  temperature?: number;
  maxTokens?: number;
  signal?: AbortSignal;
  onDelta?: (text: string) => void;
  enabledTools?: string[];
}

const MAX_RETRIES = 4;

export async function chat(messages: ChatMessage[], opts: ChatOptions): Promise<ChatResult> {
  const body: Record<string, unknown> = {
    model: opts.model,
    messages,
    stream: true,
    temperature: opts.temperature ?? 0.4,
    max_tokens: opts.maxTokens ?? 8192,
  };
  if (opts.enabledTools) {
    body.compound_custom = { tools: { enabled_tools: opts.enabledTools } };
  }

  let lastError: unknown;
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    if (attempt > 0) {
      const wait = Math.min(2 ** attempt * 1000, 15000);
      logger.warn("groq.retry", { attempt, wait });
      await new Promise((r) => setTimeout(r, wait));
    }
    try {
      const started = Date.now();
      const res = await fetch(API_URL, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${GROQ_API_KEY}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
        signal: opts.signal,
      });
      if (res.status === 429 || res.status >= 500) {
        lastError = new Error(`HTTP ${res.status}: ${(await res.text()).slice(0, 300)}`);
        continue;
      }
      if (!res.ok) {
        const detail = (await res.text()).slice(0, 500);
        throw new Error(`Groq API error ${res.status}: ${detail}`);
      }
      const result = await readStream(res, opts.onDelta);
      const elapsed = Date.now() - started;
      logger.info("groq.chat", { model: opts.model, ms: elapsed, usage: result.usage });
      trace("api.response", {
        model: opts.model,
        ms: elapsed,
        usage: result.usage,
        content_chars: result.content.length,
      });
      return result;
    } catch (err) {
      if (opts.signal?.aborted) throw new Error("aborted");
      lastError = err;
      const msg = String(err);
      if (msg.includes("Groq API error 4")) throw err;
    }
  }
  trace("api.error", { model: opts.model, error: String(lastError) });
  throw new Error(`Groq request failed after ${MAX_RETRIES + 1} attempts: ${lastError}`);
}

async function readStream(res: Response, onDelta?: (t: string) => void): Promise<ChatResult> {
  const reader = res.body!.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let content = "";
  let reasoning = "";
  let usage: Usage = { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
  let model = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";
    for (const line of lines) {
      const data = line.startsWith("data: ") ? line.slice(6).trim() : "";
      if (!data || data === "[DONE]") continue;
      try {
        const chunk = JSON.parse(data);
        model = chunk.model ?? model;
        const delta = chunk.choices?.[0]?.delta;
        if (delta?.content) {
          content += delta.content;
          onDelta?.(delta.content);
        }
        if (delta?.reasoning) reasoning += delta.reasoning;
        if (chunk.usage) usage = chunk.usage;
        if (chunk.x_groq?.usage) usage = chunk.x_groq.usage;
      } catch {
        // Skip malformed SSE chunks.
      }
    }
  }
  if (!usage.total_tokens) {
    usage = {
      prompt_tokens: Math.ceil(content.length / 4),
      completion_tokens: Math.ceil(content.length / 4),
      total_tokens: Math.ceil(content.length / 2),
    };
  }
  return { content, reasoning: reasoning || undefined, usage, model };
}
